  +                  >
  +                    Apply to dossier
  +                  </button>
  +                )}
  +                {props.onDismissObservation$ && (
  +                  <button
  +                    type="button"
  +                    onClick$={() => props.onDismissObservation$?.(index)}
  +                    class="btn-paper !px-2.5 !py-1 !text-[0.65rem]"
  +                  >
  +                    Dismiss suggestion
  +                  </button>
  +                )}
  +              </div>
  +            </article>
  +          ))}
  +        </section>
  +      )}
  +    </section>
  +  );
  +});

  diff --git a/src/components/onboarding/dossier-folio.tsx b/src/components/onboarding/dossier-folio.tsx
  new file mode 100644
  index 0000000..346d868
  --- /dev/null
  +++ b/src/components/onboarding/dossier-folio.tsx
  @@ -0,0 +1,71 @@
  +import type { JSXOutput } from "@builder.io/qwik";
  +
  +/**
  + * The folio — the one frame both authoring surfaces are filed into.
  + *
  + * The form and the conversation used to be two different pages that happened
  + * to share a colour palette: the form was a card floating on a `min-h-screen`
  + * document that scrolled, the conversation was a full-bleed transcript with
  + * page-wide chrome above it. Switching between them redrew everything, which
  + * made a change of *surface* read like a change of *place*.
  + *
  + * Here they are the same object. One sheet, locked to the viewport, with the
  + * route chrome filed into its top edge, the live dossier on the left leaf, and
  + * whatever the writer is actually working in on the right. Because both
  + * surfaces emit the identical frame in the identical position, switching them
  + * only swaps the leaves — and the right leaf is keyed so the swap feeds in
  + * like paper rather than blinking.
  + *
  + * This is deliberately an *inline* component (a plain function, not
  + * `component$`) taking its three regions as JSX props rather than as slots.
  + * Projected content that contains a component does not pick up prop changes
  + * from the projecting parent — the live dossier froze on whichever field was
  + * active when it first mounted. Rendering inline keeps the leaves inside the
  + * caller's own reactivity, where they belong.
  + */
  +interface DossierFolioProps {
  +  /**
  +   * Which surface is filling the right leaf. Keys the feed animation, so a
  +   * surface switch is a sheet change rather than a repaint.
  +   */
  +  surface: "form" | "conversational";
  +  /** The top bar, filed into the folio's edge. */
  +  chrome: JSXOutput;
  +  /** The left leaf: the brief as it currently stands. */
  +  dossier: JSXOutput;
  +  /** The right leaf: the question, or the transcript. */
  +  leaf: JSXOutput;
  +  /** Rendered outside the folio — transient overlays like the sending pip. */
  +  overlays?: JSXOutput;
  +}
  +
  +export const DossierFolio = (props: DossierFolioProps) => {
  +  return (
  +    <main class="flex h-[100dvh] min-h-0 flex-col overflow-hidden paper-sheet paper-foxed">
  +      {props.overlays}
  +      <div class="mx-auto flex min-h-0 w-full max-w-[92rem] flex-1 flex-col px-3 py-3 sm:px-5 sm:py-4">
  +        <div class="folio flex min-h-0 flex-1 flex-col overflow-hidden">
  +          {props.chrome}
  +
  +          <div class="grid min-h-0 flex-1 overflow-hidden lg:grid-cols-[minmax(0,1fr)_minmax(0,1.02fr)]">
  +            {/* ── LEFT LEAF: the dossier as it stands ─────────────────── */}
  +            <div
  +              class="folio-column border-b border-[var(--color-paper-3)] px-5 py-4 lg:border-b-0 lg:border-r"
  +              style="background: linear-gradient(165deg, var(--color-paper-soft) 0%, var(--color-paper-2) 100%);"
  +            >
  +              {props.dossier}
  +            </div>
  +
  +            {/* ── RIGHT LEAF: the surface the writer is working in ────── */}
  +            <div
  +              key={props.surface}
  +              class="folio-shift flex min-h-0 flex-col bg-[var(--color-paper)]"
  +            >
  +              {props.leaf}
  +            </div>
  +          </div>
  +        </div>
  +      </div>
  +    </main>
  +  );
  +};

  diff --git a/src/utils/dossier-check.test.ts b/src/utils/dossier-check.test.ts
  new file mode 100644
  index 0000000..8fb7a14
  --- /dev/null
  +++ b/src/utils/dossier-check.test.ts
  @@ -0,0 +1,97 @@
  +import { describe, expect, test } from "bun:test";
  +import type { ProjectInterviewAnswers } from "../types";
  +import { parseDossierCheckResult } from "./dossier-check";
  +
  +const answers: ProjectInterviewAnswers = {
  +  workingTitle: "Old title",
  +  format: "Essay",
  +  audience: "Policy readers",
  +  goal: "Explain the tradeoff",
  +  tone: "Measured",
  +  constraints: "Cite every numerical claim",
  +  successSignal: "The reader can describe the tradeoff",
  +};
  +
  +describe("parseDossierCheckResult", () => {
  +  test("accepts a valid empty drift report", () => {
  +    expect(
  +      parseDossierCheckResult('{"observations":[]}', "hosted", answers),
  +    ).toEqual({ observations: [], provider: "hosted" });
  +  });
  +
  +  test("narrows fields, fills current values, and preserves first-seen order", () => {
  +    const result = parseDossierCheckResult(
  +      JSON.stringify({
  +        observations: [
  +          {
  +            field: "tone",
  +            suggested: "Sharper",
  +            reason: "The draft is more direct than the filed tone.",
  +          },
  +          {
  +            field: "unknown",
  +            current: "x",
  +            suggested: "y",
  +            reason: "invalid",
  +          },
  +          {
  +            field: "tone",
  +            current: "Measured",
  +            suggested: "Different duplicate",
  +            reason: "duplicate",
  +          },
  +          {
  +            field: "workingTitle",
  +            current: "Old title",
  +            suggested: "New title",
  +            reason: "The manuscript now names the central conflict.",
  +          },
  +        ],
  +      }),
  +      "local",
  +      answers,
  +    );
  +
  +    expect(result?.observations.map((item) => item.field)).toEqual([
  +      "tone",
  +      "workingTitle",
  +    ]);
  +    expect(result?.observations[0]?.current).toBe(answers.tone);
  +  });
  +
  +  test("accepts fenced JSON and drops unactionable observations", () => {
  +    const result = parseDossierCheckResult(
  +      `Here is the report:
  +      \`\`\`json
  +      {"observations":[
  +        {"field":"goal","suggested":"","reason":"No replacement"},
  +        {"field":"audience","suggested":"Editors","reason":"The draft assumes editorial vocabulary."}
  +      ]}
  +      \`\`\``,
  +      "test",
  +      answers,
  +    );
  +
  +    expect(result?.observations).toHaveLength(1);
  +    expect(result?.observations[0]?.field).toBe("audience");
  +  });
  +
  +  test("finds the report after non-JSON brace-shaped prose", () => {
  +    const result = parseDossierCheckResult(
  +      `Use {field, current, suggested, reason}. Actual report:
  +      {"observations":[{"field":"format","suggested":"Reported essay","reason":"The draft now uses a reported structure."}]}
  +      End.`,
  +      "test",
  +      answers,
  +    );
  +
  +    expect(result?.observations[0]?.field).toBe("format");
  +  });
  +
  +  test.each(["", "not json", '{"observations":{}}', '{"wrong":[]}'])(
  +    "returns null for malformed protocol output: %s",
  +    (text) => {
  +      expect(parseDossierCheckResult(text, "test", answers)).toBeNull();
  +    },
  +  );
  +});

  diff --git a/src/utils/dossier-check.ts b/src/utils/dossier-check.ts
  new file mode 100644
  index 0000000..d7d5903
  --- /dev/null
  +++ b/src/utils/dossier-check.ts
  @@ -0,0 +1,118 @@
  +import type {
  +  DossierCheckResult,
  +  DossierObservation,
  +  ProjectInterviewAnswers,
  +} from "../types";
  +
  +const DOSSIER_FIELDS = [
  +  "workingTitle",
  +  "format",
  +  "audience",
  +  "goal",
  +  "tone",
  +  "constraints",
  +  "successSignal",
  +] as const satisfies ReadonlyArray<keyof ProjectInterviewAnswers>;
  +
  +const DOSSIER_FIELD_SET = new Set<string>(DOSSIER_FIELDS);
  +
  +function stringValue(value: unknown): string {
  +  return typeof value === "string" ? value.trim() : "";
  +}
  +
  +function parsedObject(value: string): Record<string, unknown> | null {
  +  try {
  +    const parsed = JSON.parse(value) as unknown;
  +    return parsed && typeof parsed === "object"
  +      ? (parsed as Record<string, unknown>)
  +      : null;
  +  } catch {
  +    return null;
  +  }
  +}
  +
  +function jsonObjectFrom(text: string): Record<string, unknown> | null {
  +  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i)?.[1];
  +  if (fenced) {
  +    const parsed = parsedObject(fenced.trim());
  +    if (parsed) return parsed;
  +  }
  +
  +  // Find the first balanced object that actually parses. This tolerates brief
  +  // prose before or after the JSON and ignores brace-shaped examples in that
  +  // prose without greedily swallowing the real report.
  +  for (let start = 0; start < text.length; start++) {
  +    if (text[start] !== "{") continue;
  +    let depth = 0;
  +    let inString = false;
  +    let escaped = false;
  +    for (let end = start; end < text.length; end++) {
  +      const char = text[end]!;
  +      if (inString) {
  +        if (escaped) escaped = false;
  +        else if (char === "\\") escaped = true;
  +        else if (char === '"') inString = false;
  +        continue;
  +      }
  +      if (char === '"') {
  +        inString = true;
  +        continue;
  +      }
  +      if (char === "{") depth += 1;
  +      if (char === "}") depth -= 1;
  +      if (depth !== 0) continue;
  +      const parsed = parsedObject(text.slice(start, end + 1));
  +      if (parsed) return parsed;
  +      break;
  +    }
  +  }
  +  return null;
  +}
  +
  +/**
  + * Parse and narrow the model's drift report.
  + *
  + * The report is writer-facing and directly mutates dossier fields, so loose
  + * `JSON.parse` output is not enough. Invalid fields are dropped, observations
  + * are de-duplicated by field in first-seen order, missing `current` values come
  + * from the brief, and a malformed top-level response is distinguishable from a
  + * valid empty report.
  + */
  +export function parseDossierCheckResult(
  +  text: string,
  +  provider: string,
  +  answers: ProjectInterviewAnswers,
  +): DossierCheckResult | null {
  +  const parsed = jsonObjectFrom(text);
  +  if (!parsed || !Array.isArray(parsed.observations)) return null;
  +
  +  const seen = new Set<keyof ProjectInterviewAnswers>();
  +  const observations: DossierObservation[] = [];
  +  for (const item of parsed.observations) {
  +    if (!item || typeof item !== "object") continue;
  +    const record = item as Record<string, unknown>;
  +    const field = stringValue(record.field);
  +    if (!DOSSIER_FIELD_SET.has(field)) continue;
  +    const typedField = field as keyof ProjectInterviewAnswers;
  +    if (seen.has(typedField)) continue;
  +
  +    const suggested = stringValue(record.suggested);
  +    const reason = stringValue(record.reason);
  +    // A report without an actionable replacement or an explanation cannot be
  +    // meaningfully applied or assessed by the writer.
  +    if (!suggested || !reason) continue;
  +
  +    observations.push({
  +      field: typedField,
  +      current: stringValue(record.current) || answers[typedField],
  +      suggested,
  +      reason,
  +    });
  +    seen.add(typedField);
  +  }
  +
  +  return {
  +    observations: observations.slice(0, DOSSIER_FIELDS.length),
  +    provider,
  +  };
  +}

