  +  font-size: 0.6rem;
  +  letter-spacing: 0.1em;
  +  line-height: 1;
  +  padding: 0.28rem 0.32rem 0.34rem;
  +  color: var(--color-ink-muted);
  +  border-bottom: 2px solid transparent;
  +  transition:
  +    color 0.15s ease,
  +    border-color 0.15s ease;
  +}
  +.folio-rail-step:hover {
  +  color: var(--color-ink);
