  diff --git a/src/components/brief/dossier-preview.tsx b/src/components/brief/dossier-preview.tsx
  new file mode 100644
  index 0000000..5789881
  --- /dev/null
  +++ b/src/components/brief/dossier-preview.tsx
  @@ -0,0 +1,361 @@
  +import { component$, type PropFunction } from "@builder.io/qwik";
  +import type {
  +  DossierAttachment,
  +  DossierCheckResult,
  +  DossierProbe,
  +  ProjectInterviewAnswers,
  +} from "../../types";
  +import { isAnswered, probeAnswerText } from "../../utils/dossier-probes";
  +
  +const FIELD_LABELS: Record<keyof ProjectInterviewAnswers, string> = {
  +  workingTitle: "Working title",
  +  format: "Format",
  +  audience: "Audience",
  +  goal: "Goal",
  +  tone: "Tone",
  +  constraints: "Non-negotiables",
  +  successSignal: "Success signal",
  +};
  +
  +const FIELD_ORDER: Array<keyof ProjectInterviewAnswers> = [
  +  "workingTitle",
  +  "format",
  +  "audience",
  +  "goal",
  +  "tone",
  +  "constraints",
  +  "successSignal",
  +];
  +
  +interface DossierPreviewProps {
  +  answers: ProjectInterviewAnswers;
  +  probes: DossierProbe[];
  +  attachments: DossierAttachment[];
  +  activeField?: keyof ProjectInterviewAnswers;
  +  existingMaterialWords?: number;
  +  mode: "first-run" | "refine";
  +  reviewedFieldCount?: number;
  +  draftReview?: DossierCheckResult | null;
  +  draftReviewLoading?: boolean;
  +  draftReviewError?: string | null;
  +  /**
  +   * Optional per-field marker class. The conversation surface uses it to show
  +   * how confident the room is in a field it inferred from talk rather than
  +   * from a typed answer; the form leaves it unset, because a field the writer
  +   * typed themselves has nothing to be uncertain about.
  +   */
  +  fieldTone?: Partial<Record<keyof ProjectInterviewAnswers, string>>;
  +  /** Replaces the working-title masthead — the conversation names its own state. */
  +  headline?: string;
  +  onJumpToField$?: PropFunction<(field: keyof ProjectInterviewAnswers) => void>;
  +  onReadDraft$?: PropFunction<() => void>;
  +  onApplyObservation$?: PropFunction<(index: number) => void>;
  +  onDismissObservation$?: PropFunction<(index: number) => void>;
  +}
  +
  +/**
  + * The live dossier occupies the folio's left leaf. It is useful working
  + * context, not a second summary card: every field is visible, the field being
  + * typed carries a caret so the sheet visibly takes the strike, answered
  + * Particulars are retained in order, and draft drift is reviewed in place.
  + *
  + * Density is the whole design constraint. The folio is locked to one viewport,
  + * so this side earns its height in compact rows: long values clamp to three
  + * lines unless they are the field under the carriage, the ledger collapses to
  + * a single struck line, and the draft-alignment block is a one-line bar until
  + * there is something to report.
  + */
  +export const DossierPreview = component$((props: DossierPreviewProps) => {
  +  const answeredProbes = props.probes.filter(isAnswered);
  +  const completedFields = Math.max(
  +    0,
  +    Math.min(
  +      FIELD_ORDER.length,
  +      props.reviewedFieldCount ??
  +        FIELD_ORDER.filter((field) => props.answers[field].trim().length > 0)
  +          .length,
  +    ),
  +  );
  +  const hasReview = props.draftReview !== undefined || !!props.onReadDraft$;
  +  const observations = props.draftReview?.observations ?? [];
  +
  +  return (
  +    <section aria-labelledby="atr-title">
  +      <div class="flex items-center justify-between gap-3">
  +        <div class="min-w-0">
  +          <p class="dept-label">
  +            {props.mode === "refine" ? "Edition · Revised" : "Working copy"}
  +          </p>
  +          <h1
  +            id="atr-title"
  +            class="mt-0.5 truncate text-[1.15rem] leading-tight text-[var(--color-ink)]"
  +            style={{
  +              fontFamily: "var(--font-display)",
  +              fontWeight: 700,
  +              letterSpacing: "-0.015em",
  +            }}
  +          >
  +            {props.headline ??
  +              (props.answers.workingTitle.trim() || "Untitled dossier")}
  +          </h1>
  +        </div>
  +        <span class="stamp shrink-0 !px-2 !py-[0.15rem] !text-[0.55rem]">
  +          {completedFields} / {FIELD_ORDER.length} reviewed
  +        </span>
  +      </div>
  +
  +      <dl class="mt-3 grid gap-1.5 sm:grid-cols-2">
  +        {FIELD_ORDER.map((field) => {
  +          const active = props.activeField === field;
  +          const value = props.answers[field];
  +          const body = (
  +            <>
  +              <dt class="dept-label !text-[0.55rem] !tracking-[0.24em] flex items-center gap-1.5">
  +                {props.fieldTone && (
  +                  <span
  +                    class={`inline-block h-1.5 w-1.5 shrink-0 rounded-full ${
  +                      props.fieldTone[field] ?? "bg-[var(--color-paper-3)]"
  +                    }`}
  +                    aria-hidden="true"
  +                  />
  +                )}
  +                {FIELD_LABELS[field]}
  +              </dt>
  +              <dd
  +                class="mt-0.5 text-[0.76rem] leading-[1.35] text-[var(--color-ink-light)] break-words"
  +                style={{
  +                  fontFamily: "var(--font-serif)",
  +                  ...(active
  +                    ? {}
  +                    : {
  +                        display: "-webkit-box",
  +                        WebkitLineClamp: "3",
  +                        WebkitBoxOrient: "vertical",
  +                        overflow: "hidden",
  +                      }),
  +                }}
  +              >
  +                {value || (
  +                  <span class="italic text-[var(--color-ink-muted)]">
  +                    Not decided yet.
  +                  </span>
  +                )}
  +                {active && <span class="type-caret" aria-hidden="true" />}
  +              </dd>
  +            </>
  +          );
  +
  +          const shellClass = `min-w-0 border px-2.5 py-1.5 text-left ${
  +            active
  +              ? "field-live"
  +              : "border-[var(--color-paper-3)] bg-[var(--color-paper-soft)] hover:border-[var(--color-ink-muted)]"
  +          }`;
  +
  +          return props.onJumpToField$ ? (
  +            <button
  +              key={field}
  +              type="button"
  +              onClick$={() => props.onJumpToField$?.(field)}
  +              class={shellClass}
  +              aria-current={active ? "step" : undefined}
  +              title={value || `${FIELD_LABELS[field]} — not decided yet`}
  +            >
  +              {body}
  +            </button>
  +          ) : (
  +            <div
  +              key={field}
  +              class={shellClass}
  +              aria-current={active ? "step" : undefined}
  +            >
  +              {body}
  +            </div>
  +          );
  +        })}
  +      </dl>
  +
  +      <div class="mt-2.5 border border-[var(--color-paper-3)] bg-[var(--color-paper-soft)] px-2.5 py-1.5">
  +        <div class="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
  +          <p class="dept-label !text-[0.55rem]">Particulars</p>
  +          <p
  +            class="text-[0.6rem] tracking-[0.14em] uppercase text-[var(--color-ink-muted)]"
  +            style={{ fontFamily: "var(--font-typewriter)" }}
  +          >
  +            {answeredProbes.length}/{props.probes.length} answered ·{" "}
  +            {props.existingMaterialWords ?? 0} words ·{" "}
  +            {props.attachments.length} refs
  +          </p>
  +        </div>
  +        {props.probes.length > 0 ? (
  +          <ol class="mt-1 space-y-0.5">
  +            {props.probes.map((probe, index) => (
  +              <li
  +                key={probe.id}
  +                class="flex gap-1.5 text-[0.7rem] leading-[1.4] text-[var(--color-ink-light)]"
  +                style={{ fontFamily: "var(--font-serif)" }}
  +                title={
  +                  isAnswered(probe)
  +                    ? `${probe.prompt} — ${probeAnswerText(probe)}`
  +                    : probe.prompt
  +                }
  +              >
  +                <span
  +                  class="shrink-0 text-[var(--color-vermilion)]"
  +                  style={{ fontFamily: "var(--font-typewriter)" }}
  +                >
  +                  {index + 1}.
  +                </span>
  +                <span class="min-w-0 truncate">
  +                  {isAnswered(probe) ? (
  +                    <>
  +                      <span class="text-[var(--color-ink-muted)]">
  +                        {probe.prompt}
  +                      </span>{" "}
  +                      <span class="text-[var(--color-ink)]">
  +                        {probeAnswerText(probe)}
  +                      </span>
  +                    </>
  +                  ) : (
  +                    <>
  +                      <span class="text-[var(--color-ink-muted)]">
  +                        {probe.prompt}
  +                      </span>{" "}
  +                      <span class="italic text-[var(--color-ink-muted)]">
  +                        Awaiting an answer.
  +                      </span>
  +                    </>
  +                  )}
  +                </span>
  +              </li>
  +            ))}
  +          </ol>
  +        ) : (
  +          <p
  +            class="mt-1 text-[0.7rem] leading-[1.4] text-[var(--color-ink-muted)]"
  +            style={{ fontFamily: "var(--font-serif)" }}
  +          >
  +            The Particulars questions will sharpen the softest parts of this
  +            brief.
  +          </p>
  +        )}
  +      </div>
  +
  +      {hasReview && (
  +        <section class="mt-2.5 border border-[var(--color-paper-3)] bg-[var(--color-paper)] px-2.5 py-2">
  +          <div class="flex flex-wrap items-center justify-between gap-2">
  +            <div class="min-w-0">
  +              <p class="dept-label !text-[0.55rem]">Draft alignment</p>
  +              <p
  +                class="text-[0.72rem] leading-[1.4] text-[var(--color-ink-muted)]"
  +                style={{ fontFamily: "var(--font-serif)" }}
  +              >
  +                Has the manuscript outgrown the brief? Nothing changes until you
  +                apply a suggestion.
  +              </p>
  +            </div>
  +            {props.onReadDraft$ && (
  +              <button
  +                type="button"
  +                onClick$={props.onReadDraft$}
  +                disabled={props.draftReviewLoading}
  +                class="btn-press shrink-0 !px-2.5 !py-1 !text-[0.65rem] disabled:opacity-40"
  +              >
  +                {props.draftReviewLoading ? "Reading draft…" : "Read my draft"}
  +              </button>
  +            )}
  +          </div>
  +
  +          {props.draftReviewLoading && (
  +            <p
  +              class="mt-2 flex items-center gap-2 text-[0.7rem] text-[var(--color-ink-muted)]"
  +              style={{ fontFamily: "var(--font-typewriter)" }}
  +              role="status"
  +            >
  +              <span
  +                class="h-2 w-2 rounded-full bg-[var(--color-mustard)] interview-stream-pulse"
  +                aria-hidden="true"
  +              />
  +              Comparing the manuscript with all seven dossier fields.
  +            </p>
  +          )}
  +
  +          {props.draftReviewError && (
  +            <p
  +              class="mt-2 border border-[var(--color-vermilion)] bg-[color-mix(in_srgb,var(--color-vermilion)_7%,var(--color-paper))] px-2.5 py-1.5 text-[0.72rem] leading-[1.45] text-[var(--color-ink)]"
  +              style={{ fontFamily: "var(--font-serif)" }}
  +              role="alert"
  +            >
  +              {props.draftReviewError}
  +            </p>
  +          )}
  +
  +          {!props.draftReviewLoading &&
  +            props.draftReview &&
  +            observations.length === 0 && (
  +              <p
  +                class="mt-2 border border-[var(--color-accent-green)] bg-[color-mix(in_srgb,var(--color-accent-green)_8%,var(--color-paper))] px-2.5 py-1.5 text-[0.72rem] leading-[1.45] text-[var(--color-ink-light)]"
  +                style={{ fontFamily: "var(--font-serif)" }}
  +                role="status"
  +              >
  +                No drift found. The current manuscript still matches the
  +                dossier.
  +              </p>
  +            )}
  +
  +          {observations.map((observation, index) => (
  +            <article
  +              key={`${observation.field}-${observation.suggested}-${index}`}
  +              class="mt-2 border border-[var(--color-paper-3)] bg-[var(--color-paper-soft)] px-2.5 py-2 folio-shift"
  +            >
  +              <p class="dept-label !text-[0.55rem]">
  +                {FIELD_LABELS[observation.field]}
  +              </p>
  +              <p
  +                class="mt-1 text-[0.74rem] leading-[1.45] text-[var(--color-ink)]"
  +                style={{ fontFamily: "var(--font-serif)" }}
  +              >
  +                {observation.reason}
  +              </p>
  +              <dl class="mt-1.5 grid gap-1.5 text-[0.7rem] sm:grid-cols-2">
  +                <div class="border border-[var(--color-paper-3)] bg-[var(--color-paper)] px-2 py-1.5">
  +                  <dt class="dept-label !text-[0.55rem]">Filed now</dt>
  +                  <dd class="mt-0.5 leading-[1.4] text-[var(--color-ink-light)]">
  +                    {observation.current ||
  +                      props.answers[observation.field] ||
  +                      "Not filed"}
  +                  </dd>
  +                </div>
  +                <div class="border border-[var(--color-mustard)] bg-[var(--color-paper)] px-2 py-1.5">
  +                  <dt class="dept-label !text-[0.55rem]">Suggested</dt>
  +                  <dd class="mt-0.5 leading-[1.4] text-[var(--color-ink)]">
  +                    {observation.suggested}
  +                  </dd>
  +                </div>
  +              </dl>
  +              <div class="mt-1.5 flex flex-wrap items-center gap-2">
  +                {observation.suggested && props.onApplyObservation$ && (
  +                  <button
  +                    type="button"
  +                    onClick$={() => props.onApplyObservation$?.(index)}
  +                    class="btn-press !px-2.5 !py-1 !text-[0.65rem]"
  +                  >
  +                    Apply to dossier
  +                  </button>
  +                )}
  +                {props.onDismissObservation$ && (
  +                  <button
  +                    type="button"
  +                    onClick$={() => props.onDismissObservation$?.(index)}
  +                    class="btn-paper !px-2.5 !py-1 !text-[0.65rem]"
  +                  >
  +                    Dismiss suggestion
  +                  </button>
  +                )}
  +              </div>
  +            </article>
  +          ))}
  +        </section>
  +      )}
  +    </section>
  +  );
  +});

  diff --git a/src/components/onboarding/dossier-folio.tsx b/src/components/onboarding/dossier-folio.tsx
  new file mode 100644
  index 0000000..346d868
  --- /dev/null
  +++ b/src/components/onboarding/dossier-folio.tsx
  @@ -0,0 +1,71 @@
  +import type { JSXOutput } from "@builder.io/qwik";
  +
  +/**
  + * The folio — the one frame both authoring surfaces are filed into.
  + *
  + * The form and the conversation used to be two different pages that happened
  + * to share a colour palette: the form was a card floating on a `min-h-screen`
  + * document that scrolled, the conversation was a full-bleed transcript with
  + * page-wide chrome above it. Switching between them redrew everything, which
  + * made a change of *surface* read like a change of *place*.
  + *
  + * Here they are the same object. One sheet, locked to the viewport, with the
  + * route chrome filed into its top edge, the live dossier on the left leaf, and
  + * whatever the writer is actually working in on the right. Because both
  + * surfaces emit the identical frame in the identical position, switching them
  + * only swaps the leaves — and the right leaf is keyed so the swap feeds in
  + * like paper rather than blinking.
  + *
  + * This is deliberately an *inline* component (a plain function, not
  + * `component$`) taking its three regions as JSX props rather than as slots.
  + * Projected content that contains a component does not pick up prop changes
  + * from the projecting parent — the live dossier froze on whichever field was
  + * active when it first mounted. Rendering inline keeps the leaves inside the
  + * caller's own reactivity, where they belong.
  + */
  +interface DossierFolioProps {
  +  /**
  +   * Which surface is filling the right leaf. Keys the feed animation, so a
  +   * surface switch is a sheet change rather than a repaint.
  +   */
  +  surface: "form" | "conversational";
  +  /** The top bar, filed into the folio's edge. */
  +  chrome: JSXOutput;
  +  /** The left leaf: the brief as it currently stands. */
  +  dossier: JSXOutput;
  +  /** The right leaf: the question, or the transcript. */
  +  leaf: JSXOutput;
  +  /** Rendered outside the folio — transient overlays like the sending pip. */
  +  overlays?: JSXOutput;
  +}
  +
  +export const DossierFolio = (props: DossierFolioProps) => {
  +  return (
  +    <main class="flex h-[100dvh] min-h-0 flex-col overflow-hidden paper-sheet paper-foxed">
  +      {props.overlays}
  +      <div class="mx-auto flex min-h-0 w-full max-w-[92rem] flex-1 flex-col px-3 py-3 sm:px-5 sm:py-4">
  +        <div class="folio flex min-h-0 flex-1 flex-col overflow-hidden">
  +          {props.chrome}
  +
  +          <div class="grid min-h-0 flex-1 overflow-hidden lg:grid-cols-[minmax(0,1fr)_minmax(0,1.02fr)]">
  +            {/* ── LEFT LEAF: the dossier as it stands ─────────────────── */}
  +            <div
  +              class="folio-column border-b border-[var(--color-paper-3)] px-5 py-4 lg:border-b-0 lg:border-r"
  +              style="background: linear-gradient(165deg, var(--color-paper-soft) 0%, var(--color-paper-2) 100%);"
  +            >
  +              {props.dossier}
  +            </div>
  +
  +            {/* ── RIGHT LEAF: the surface the writer is working in ────── */}
  +            <div
  +              key={props.surface}
  +              class="folio-shift flex min-h-0 flex-col bg-[var(--color-paper)]"
  +            >
  +              {props.leaf}
  +            </div>
  +          </div>
  +        </div>
  +      </div>
  +    </main>
  +  );
  +};

  diff --git a/src/utils/dossier-check.test.ts b/src/utils/dossier-check.test.ts
  new file mode 100644
  index 0000000..8fb7a14
  --- /dev/null
  +++ b/src/utils/dossier-check.test.ts
  @@ -0,0 +1,97 @@
  +import { describe, expect, test } from "bun:test";
  +import type { ProjectInterviewAnswers } from "../types";
  +import { parseDossierCheckResult } from "./dossier-check";
  +
  +const answers: ProjectInterviewAnswers = {
  +  workingTitle: "Old title",
  +  format: "Essay",
  +  audience: "Policy readers",
  +  goal: "Explain the tradeoff",
  +  tone: "Measured",
  +  constraints: "Cite every numerical claim",
  +  successSignal: "The reader can describe the tradeoff",
  +};
  +
  +describe("parseDossierCheckResult", () => {
  +  test("accepts a valid empty drift report", () => {
  +    expect(
  +      parseDossierCheckResult('{"observations":[]}', "hosted", answers),
  +    ).toEqual({ observations: [], provider: "hosted" });
  +  });
  +
  +  test("narrows fields, fills current values, and preserves first-seen order", () => {
  +    const result = parseDossierCheckResult(
  +      JSON.stringify({
  +        observations: [
  +          {
  +            field: "tone",
  +            suggested: "Sharper",
  +            reason: "The draft is more direct than the filed tone.",
  +          },
  +          {
  +            field: "unknown",
  +            current: "x",
  +            suggested: "y",
  +            reason: "invalid",
  +          },
  +          {
  +            field: "tone",
  +            current: "Measured",
  +            suggested: "Different duplicate",
  +            reason: "duplicate",
  +          },
  +          {
  +            field: "workingTitle",
  +            current: "Old title",
  +            suggested: "New title",
  +            reason: "The manuscript now names the central conflict.",
  +          },
  +        ],
  +      }),
  +      "local",
  +      answers,
  +    );
  +
  +    expect(result?.observations.map((item) => item.field)).toEqual([
  +      "tone",
  +      "workingTitle",
  +    ]);
  +    expect(result?.observations[0]?.current).toBe(answers.tone);
  +  });
  +
  +  test("accepts fenced JSON and drops unactionable observations", () => {
  +    const result = parseDossierCheckResult(
  +      `Here is the report:
  +      \`\`\`json
  +      {"observations":[
  +        {"field":"goal","suggested":"","reason":"No replacement"},
  +        {"field":"audience","suggested":"Editors","reason":"The draft assumes editorial vocabulary."}
  +      ]}
  +      \`\`\``,
  +      "test",
  +      answers,
  +    );
  +
  +    expect(result?.observations).toHaveLength(1);
  +    expect(result?.observations[0]?.field).toBe("audience");
  +  });
  +
  +  test("finds the report after non-JSON brace-shaped prose", () => {
  +    const result = parseDossierCheckResult(
  +      `Use {field, current, suggested, reason}. Actual report:
  +      {"observations":[{"field":"format","suggested":"Reported essay","reason":"The draft now uses a reported structure."}]}
  +      End.`,
  +      "test",
  +      answers,
  +    );
  +
  +    expect(result?.observations[0]?.field).toBe("format");
  +  });
  +
  +  test.each(["", "not json", '{"observations":{}}', '{"wrong":[]}'])(
  +    "returns null for malformed protocol output: %s",
  +    (text) => {
  +      expect(parseDossierCheckResult(text, "test", answers)).toBeNull();
  +    },
  +  );
  +});

  diff --git a/src/utils/dossier-check.ts b/src/utils/dossier-check.ts
  new file mode 100644
  index 0000000..d7d5903
  --- /dev/null
  +++ b/src/utils/dossier-check.ts
  @@ -0,0 +1,118 @@
  +import type {
  +  DossierCheckResult,
  +  DossierObservation,
  +  ProjectInterviewAnswers,
  +} from "../types";
  +
  +const DOSSIER_FIELDS = [
  +  "workingTitle",
  +  "format",
  +  "audience",
  +  "goal",
  +  "tone",
  +  "constraints",
  +  "successSignal",
  +] as const satisfies ReadonlyArray<keyof ProjectInterviewAnswers>;
  +
  +const DOSSIER_FIELD_SET = new Set<string>(DOSSIER_FIELDS);
  +
  +function stringValue(value: unknown): string {
  +  return typeof value === "string" ? value.trim() : "";
  +}
  +
  +function parsedObject(value: string): Record<string, unknown> | null {
  +  try {
  +    const parsed = JSON.parse(value) as unknown;
  +    return parsed && typeof parsed === "object"
  +      ? (parsed as Record<string, unknown>)
  +      : null;
  +  } catch {
  +    return null;
  +  }
  +}
  +
  +function jsonObjectFrom(text: string): Record<string, unknown> | null {
  +  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i)?.[1];
  +  if (fenced) {
  +    const parsed = parsedObject(fenced.trim());
  +    if (parsed) return parsed;
  +  }
  +
  +  // Find the first balanced object that actually parses. This tolerates brief
  +  // prose before or after the JSON and ignores brace-shaped examples in that
  +  // prose without greedily swallowing the real report.
  +  for (let start = 0; start < text.length; start++) {
  +    if (text[start] !== "{") continue;
  +    let depth = 0;
  +    let inString = false;
  +    let escaped = false;
  +    for (let end = start; end < text.length; end++) {
  +      const char = text[end]!;
  +      if (inString) {
  +        if (escaped) escaped = false;
  +        else if (char === "\\") escaped = true;
  +        else if (char === '"') inString = false;
  +        continue;
  +      }
  +      if (char === '"') {
  +        inString = true;
  +        continue;
  +      }
  +      if (char === "{") depth += 1;
  +      if (char === "}") depth -= 1;
  +      if (depth !== 0) continue;
  +      const parsed = parsedObject(text.slice(start, end + 1));
  +      if (parsed) return parsed;
  +      break;
  +    }
  +  }
  +  return null;
  +}
  +
  +/**
  + * Parse and narrow the model's drift report.
  + *
  + * The report is writer-facing and directly mutates dossier fields, so loose
  + * `JSON.parse` output is not enough. Invalid fields are dropped, observations
  + * are de-duplicated by field in first-seen order, missing `current` values come
  + * from the brief, and a malformed top-level response is distinguishable from a
  + * valid empty report.
  + */
  +export function parseDossierCheckResult(
  +  text: string,
  +  provider: string,
  +  answers: ProjectInterviewAnswers,
  +): DossierCheckResult | null {
  +  const parsed = jsonObjectFrom(text);
  +  if (!parsed || !Array.isArray(parsed.observations)) return null;
  +
  +  const seen = new Set<keyof ProjectInterviewAnswers>();
  +  const observations: DossierObservation[] = [];
  +  for (const item of parsed.observations) {
  +    if (!item || typeof item !== "object") continue;
  +    const record = item as Record<string, unknown>;
  +    const field = stringValue(record.field);
  +    if (!DOSSIER_FIELD_SET.has(field)) continue;
  +    const typedField = field as keyof ProjectInterviewAnswers;
  +    if (seen.has(typedField)) continue;
  +
  +    const suggested = stringValue(record.suggested);
  +    const reason = stringValue(record.reason);
  +    // A report without an actionable replacement or an explanation cannot be
  +    // meaningfully applied or assessed by the writer.
  +    if (!suggested || !reason) continue;
  +
  +    observations.push({
  +      field: typedField,
  +      current: stringValue(record.current) || answers[typedField],
  +      suggested,
  +      reason,
  +    });
  +    seen.add(typedField);
  +  }
  +
  +  return {
  +    observations: observations.slice(0, DOSSIER_FIELDS.length),
  +    provider,
  +  };
  +}

